    public interface HibernateBuilders {
        /**
         * Hibernate (camel-hibernate)
         * Run HQL queries, look up, insert and upsert entities, and poll
         * entities from a relational database with Hibernate ORM.
         * 
         * Category: database
         * Since: 4.24
         * Maven coordinates: org.apache.camel:camel-hibernate
         * 
         * @return the dsl builder for the headers' name.
         */
        default HibernateHeaderNameBuilder hibernate() {
            return HibernateHeaderNameBuilder.INSTANCE;
        }
        /**
         * Hibernate (camel-hibernate)
         * Run HQL queries, look up, insert and upsert entities, and poll
         * entities from a relational database with Hibernate ORM.
         * 
         * Category: database
         * Since: 4.24
         * Maven coordinates: org.apache.camel:camel-hibernate
         * 
         * Syntax: <code>hibernate:entityClassName</code>
         * 
         * Path parameter: entityClassName (required)
         * The fully qualified class name of the Hibernate entity. It is the
         * result type of the selection query and the entity type of the
         * natural-id lookup. The mutation query and the stateless operations do
         * not use it.
         * 
         * @param path entityClassName
         * @return the dsl builder
         */
        default HibernateEndpointBuilder hibernate(String path) {
            return HibernateEndpointBuilderFactory.endpointBuilder("hibernate", path);
        }
        /**
         * Hibernate (camel-hibernate)
         * Run HQL queries, look up, insert and upsert entities, and poll
         * entities from a relational database with Hibernate ORM.
         * 
         * Category: database
         * Since: 4.24
         * Maven coordinates: org.apache.camel:camel-hibernate
         * 
         * Syntax: <code>hibernate:entityClassName</code>
         * 
         * Path parameter: entityClassName (required)
         * The fully qualified class name of the Hibernate entity. It is the
         * result type of the selection query and the entity type of the
         * natural-id lookup. The mutation query and the stateless operations do
         * not use it.
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path entityClassName
         * @return the dsl builder
         */
        default HibernateEndpointBuilder hibernate(String componentName, String path) {
            return HibernateEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
    /**
     * The builder of headers' name for the Hibernate component.
     */
    public static class HibernateHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final HibernateHeaderNameBuilder INSTANCE = new HibernateHeaderNameBuilder();

        /**
         * The named parameters, as a Map, that the producer binds to the
         * selection or mutation query. For a natural-id lookup the entries are
         * added to the naturalId values and replace those of the same name. The
         * values are not evaluated as expressions.
         * 
         * The option is a: {@code Map<String, Object>} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code HibernateParameters}.
         */
        public String hibernateParameters() {
            return "CamelHibernateParameters";
        }
    }
    static HibernateEndpointBuilder endpointBuilder(String componentName, String path) {
        class HibernateEndpointBuilderImpl extends AbstractEndpointBuilder implements HibernateEndpointBuilder, AdvancedHibernateEndpointBuilder {
            public HibernateEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new HibernateEndpointBuilderImpl(path);
    }
